from analyze import *
import html,textwrap,hashlib,subprocess
from matplotlib.backends.backend_pdf import PdfPages

def fmt(x):return f'{x:.6g}' if isinstance(x,(int,float)) else str(x)
def table(headers,rows):return '<table><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(fmt(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</table>'
def image(path):return f'<a href="{path}"><img src="{path}"></a>'
def get(name):return json.loads((ROOT/'analysis'/name/'summary.json').read_text())
def paragraph(x):return '<p>'+x+'</p>'

def build():
 completed=[]
 for d in (ROOT/'runs').iterdir():
  if (d/'complete.toml').exists():
   c=tomllib.loads((d/'config.toml').read_text());z=tomllib.loads((d/'complete.toml').read_text());completed.append((d.name,c,z))
 count=len(completed);sec=sum(x[2]['elapsed_seconds'] for x in completed);storage=sum(p.stat().st_size for p in ROOT.rglob('*') if p.is_file());summaries={name:get(name) for name in ['ring_base','ring_fine','ring_halfdt','hopf_base','hopf_fine','trefoil_base','trefoil_fine'] if (ROOT/'analysis'/name/'summary.json').exists()}
 text=[];body=['<h1>Local VortexPasta topology experiments</h1>','<p>14 October 2026 · CPU · VortexPasta 0.34.19 · Julia 1.13.1</p>']
 def add(title,content):
  text.append((title,content));body.append('<h2>'+html.escape(title)+'</h2>');body.append(paragraph(html.escape(content)))
 ring=summaries.get('ring_base');fine=summaries.get('ring_fine')
 add('What actually ran',f'{count} runs have completion records, totaling {sec/60:.1f} summed in-process minutes, including startup inside the driver. Two simulation processes at most ran concurrently, each with 2 Julia threads and 1 BLAS/OpenMP thread. The directory currently occupies about {storage/2**20:.0f} MiB. Peak measured resident memory was 1.29 GiB per process; the longest individual run took 8.94 minutes. The summed simulation time stayed near the initial one-hour budget, although the Hopf family of targeted checks exceeded the initial 20-minute per-configuration aim. Full per-run and batch resource records are retained in analysis/costs.json and *_resources.txt. Pilot, preliminary, accuracy-corrected, prepared-centerline, and numerical-check runs are named separately. Every completed run retains its final checkpoint; failed setup and plotting attempts retain logs. No remote jobs or GPE simulations were launched.')
 add('Main result','The circular ring passes a stringent propagation and conservation check. Slender-core Hopf and trefoil filaments reconnect, giving respectively one and two loops. Their event timing, removed length, and post-reconnection helicity retain numerical and reconnection-model sensitivity. Wider-core GPE-convention trajectories do not reproduce the retained GPE reconnection dynamics; later node growth and artificial fragmentation limit their interpretation. These calculations demonstrate geometry and numerical behavior, not reproduction of phonon emission or the paper’s late helicity decay.')
 if ring and fine:
  add('Circular-ring result',f"At a=0.001, the periodic propagation speeds are {ring['speed_fit']:.10f} (64 nodes) and {fine['speed_fit']:.10f} (128 nodes), relative difference {abs(ring['speed_fit']/fine['speed_fit']-1):.3g}. Halving the timestep gives {get('ring_halfdt')['speed_fit']:.10f}. The 64-node maximum relative changes are length {ring['max_relative_length_change']:.3g}, energy {ring['max_relative_energy_change']:.3g}, normalized impulse {ring['max_impulse_vector_relative_change']:.3g}; max |H|/Gamma²={ring['max_abs_helicity']:.3g}. Transverse centroid drift is {ring['transverse_centroid_drift']:.3g}; maximum best-plane RMS departure is {ring['max_best_plane_rms']:.3g}. Tiny fourfold deformation is consistent with the periodic image field.")
 body.append(image('figures/ring_convergence.png'))
 for case in ['hopf','trefoil']:
  vals=[]
  for suffix in ['base','fine','halfdt','d060','d100']:
   p=ROOT/'runs'/f'{case}_{suffix}'/'events.csv'
   if p.exists():
    ev=list(csv.DictReader(p.open()));vals.append(suffix+': '+', '.join(f"{float(e['t_after']):.6f}" for e in ev[:3]))
  site_note = ' Different event indices are matched by spatial site in validation_checks.json. Doubling nodes changes the trefoil spatial order from coarse sites 1–2–3 to 3–2–1. Neither node count is divisible by three, so sampling does not preserve exact threefold symmetry; the serial algorithm also orders nearby cuts. No physically preferred order or exact simultaneity is established.' if case == 'trefoil' else ''
  add(case.capitalize()+' measured event times','Physical time t; multiply by Gamma=2.0826013773 for t*. '+ '; '.join(vals)+'. Timing brackets are one accepted step, not physical uncertainty estimates.'+site_note)
 add('Physical choices and core convention','The periodic cube has side 2π, R=1, rho=1, and Gamma=2.0826013772617338. These are local baseline choices, not verified original paper inputs. Full Ewald Biot–Savart dynamics, RK4, zero imposed flow, zero mutual friction, and NoDissipation are used. The slender control has a=0.001 (R/a=1000). Exploratory wider-core runs use a=0.1171875 and Delta=0.615 because the installed package explicitly documents this asymptotic GP healing-length convention. This is not a fitted core radius. A hollow-core Delta=0.5 would require a different radius to give the same logarithmic constant. R/xi=8.5333 in GHOST, and local curvature and strand separations become comparable to the core: the thin-filament approximation is then uncontrolled.')
 add('Ring benchmark and calibration gap','The documented unbounded prediction is U=Gamma[ln(8R/a)-Delta]/(4πR), E/rho=Gamma²R[ln(8R/a)-Delta-1]/2. The final benchmark tests both core choices and both node counts. At 128 nodes, slender unbounded speed is 1.3875083745 versus 1.3875087059 predicted; periodic speed is 1.3684490764. For the wider core, unbounded speed is 0.5980167057 versus 0.5980170436 predicted; periodic speed is 0.5789574077. The periodic correction is about -0.0190593, and must not be mistaken for core error. Existing GPE ring inputs instead have c=1, xi=0.3, Gamma=2.6657297628950194; they cannot calibrate the c=2, xi=0.1171875 cases. No compatible GPE ring calibration was available.')
 add('Initial geometry and topology','The single ring is centered at (π,π,π), with counterclockwise xy orientation. The Hopf circles follow the actual GHOST initializer: (π-1/2+cos s,π+sin s,π) and (π+1/2+cos s,π,π+sin s). Their linking number is approximately -1; positive circulation follows increasing s. The trefoil is exactly the requested analytic curve. Installed TrefoilKnot has the same signs and is scaled by 1/3, translated by π, and kept at orientation +1; a 1001-point evaluation agrees within 1.34e-15. Known circle and trefoil controls give determinants 1 and 3. Three generic trefoil projections have three-crossing diagrams and determinant 3, establishing a trefoil here; determinant alone is not a general knot classifier. Both configurations have negative chirality in the retained GHOST convention; signs are never reversed for visual agreement.')
 add('Prepared-centerline comparison','GHOST case 05 has no completed results. Cases 04 and 06 have return code 0, matching parameter hashes, retained final t=10 fields, and histories reaching t=10. Their c, xi, rho, and circulation were checked from actual inputs. Prepared t=0 curves were reused from retained NPZ caches, and independently retraced from the hash-verified imported wavefunctions using the existing oriented plaquette/bilinear-root tracer at 128³ interpolation. Both traces are closed and unambiguous. Arclength resampling produces the prepared VFM input CSVs. Preparation changes geometry; analytic and prepared initializations are separately labeled in all comparisons. The older VortexPasta ring has diagnostics through t=10.00003; the coplanar two-ring case has snapshots only through t=0.00618842 and no diagnostic/completion record proving its endpoint. It is unlinked and is not reused as a Hopf input. Existing GPE results and diagnostic limitations are retained, including the initial trefoil native-volume versus Eq. 8 line-helicity discrepancy.')
 add('Resolution and timestep','Initial node counts are 64 per ring and 128 for the trefoil, doubled in spatial checks. Dense analytic curves or retained prepared curves are resampled approximately uniformly in arclength. Quintic splines and adaptive segment-length refinement enforce nominal bounds 0.65h to 1.4h, where h is the smallest initial segment. Actual segment bounds, curvature, and node counts are recorded throughout. All final checks use Fourier mesh 48³, Ewald beta=4.5, Gaussian quadrature order 10, NUFFT oversampling 1.5/support 6, and LIA segment fraction 0.2. These are accuracy controls distinct from the GPE grid and filament nodes. The 64³/beta=5/quadrature-12 reference differs by order 10^-9 in velocity on tested initial geometries; representative pre/post-event and evolved snapshots remain below 1e-8 relative velocity difference. Ewald/quadrature error is therefore much smaller than the observed filament-resolution effects in these tests. Preliminary quadrature-4 runs had order 10^-4 velocity errors and are explicitly superseded. Timesteps combine a 0.001 cap, node-displacement cap, and 0.25 times the thin-core Kelvin period. Half-step tests halve all three caps. The thin-core Kelvin formula becomes invalid for wider cores; those exploratory runs use displacement and fixed-step caps only. Wide fine tests also reduce dt to 0.00025 and are not a pure spatial comparison; separate coarse dt/2 tests expose that limitation.')
 add('Reconnection algorithm and numerical losses','ReconnectFast is used with fixed physical distance 0.08 in the baseline and both spatial resolutions; 0.06 and 0.10 test its sensitivity. Thus the threshold is not silently scaled with node spacing. The implementation first screens node distances, considers straight local segments, rejects adjacent/two-neighbor pairs, requires approaching velocities and decreasing segment length, and accepts antiparallel or sufficiently misaligned segments (cos_max=0.97). Serial ordering is used, with up to two scans per step; multiple events can occur on one filament, and scan order is not a simultaneous multi-site solution. A read-only hook records each actual accepted event’s location, bracketing timestep, and local segment-length change. The installed package is unchanged. Total length can change through resolved stretching even without dissipation. Adaptive node insertion/removal and disappearance of unresolved small loops are tracked separately; signed refinement loss can be negative when interpolation adds length. The short operation replays measure energy before/after reconnection and refinement at the same advected geometry, separating numerical changes from smooth evolution. The straight-edge length-loss counter is not the same as the change in integrated spline length: trefoil reconnection reinterpolation can increase the latter despite a decreasing local edge sum. The operation replays measured total E/(rho V) changes of -0.00039008 from the Hopf cut, and -0.000145075 from the three trefoil cuts; trefoil refinement in the short replay added 0.000103862. These are operator-induced changes, not physical dissipation. No loss here is labeled sound radiation. For the Hopf checks, the distance thresholds 0.06/0.08/0.10 give first events at approximately 0.62232/0.61595/0.60869; dt/2 gives 0.61565, while doubled spatial resolution gives 0.62207. Thus timing is more sensitive to spatial/reconnection choices than to timestep in this interval.')
 rows=[]
 for case in ['hopf','trefoil']:
  for suffix in ['base','fine','halfdt','d060','d100']:
   name=f'{case}_{suffix}';d=ROOT/'runs'/name
   if not (d/'complete.toml').exists():continue
   c,a,sn=loadrun(d);ev=list(csv.DictReader((d/'events.csv').open()))
   rows.append([name,a['t'][-1],'/'.join(f"{float(e['t_after']):.6f}" for e in ev[:3]),int(a['loops'][-1]),int(max(a['nodes'])),a['reconnection_length_loss'][-1],a['refinement_length_loss'][-1]])
 body.append(table(['Run','Actual final t','First event times','Final loops','Max nodes','Reconnection ΔL loss','Signed refinement ΔL loss'],rows))
 for case in ['hopf','trefoil']:
  body.append(image(f'figures/{case}_convergence.png'))
 add('Helicity, geometry, and units','The native VFM diagnostic is H=Gamma integral(v_BS·ds), reported as H/Gamma². Geometric centerline helicity is sum(Wr)+2 sum(Lk), with linking and writhe tracked separately. Neither includes an independently evolved ribbon-twist degree of freedom; it is not Hänninen’s full Seifert-framed helicity. Curves are unwrapped continuously with periodic differences, checked for zero periodic winding and absence of integer linking with the 26 nearest periodic copies at representative endpoints, and aligned to a common lift for compact-loop Gauss integrals. Time-history Gauss sums use 384 samples per loop and are checked at 768 at endpoints. An independent exact straight-segment solid-angle calculation is further checked at 384/768/1536 samples of the interpolated exported curves, with a skew-segment numerical-quadrature control. It gives final Hopf centerline helicities -2.11413 (coarse) and -2.30063 (fine), versus native -2.11261 and -2.30047; the spatial difference remains. Trefoil reconstruction/diagnostic disagreement is larger and remains unresolved; near reconnection the geometric and velocity diagnostics can differ due to insufficient filament resolution and close-strand quadrature. Minimum nonadjacent segment distance excludes two neighboring sampled segments; candidate nonlocal strands additionally exclude arclength separations below one-sixth of a loop. Curvature is the nodal spline maximum. Time is reported as physical t and t*=Gamma t/R²; U*=UR/Gamma, length*=length/R, E*=V E_native/(Gamma²R), and impulse*=I/(rho Gamma R²). The package returns normalized impulse I/(rho Gamma), and energy per mass E_total/(rho V). GPE total projected energy includes compressible and core-density contributions absent from VFM, so absolute energies are not equated.')
 body.append(image('figures/trefoil_event_order.png'));body.append(image('figures/trefoil_candidate_sites.png'))
 add('Convergence limits in numbers','Over common comparison windows, doubling filament resolution changes H/Gamma² by up to 0.223 for the Hopf link and 0.589 for the trefoil. Corresponding coarse dt/2 maxima are 0.0116 and 0.1049. Before the first event, coarse/fine helicity differences remain below about 1.5e-5 (Hopf) and 4.9e-4 (trefoil). Thus the main uncertainty develops through and after the reconnection operation; post-event helicity is not converged. The threshold tests are model-sensitivity measurements, not a claim that a unique physical reconnection distance has been determined.')
 add('GHOST comparison and what remains unresolved','The prepared wide-core trajectories use the correct initial geometry and GP asymptotic core convention, but the broad core is not a controlled filament limit. Their failure to reproduce GPE timing is meaningful disagreement, not evidence that reconnection should be forced. The preliminary prepared Hopf run develops 72 imposed events and 36 loops by t≈2.5 as node growth accelerates; this is numerical/model breakdown, not a credible counterpart of the GPE trajectory. The fine/prepared and half-step runs test earlier intervals. The coarse/fine prepared Hopf runs both stay linked through t=2.1, with minimum nonlocal strand separation about 0.110, comparable to xi=0.1171875; the nominal filament criterion drec=0.08 has not been reached. This exposes the core-overlap/reconnection-model gap without retuning the threshold to GPE timing. The prepared slender trefoil has an additional fourth event near t=0.55932 and deletes one unresolved loop of straight-edge length 0.14572; by t=0.8 its signed refinement length loss is 0.25173 and energy deviation reaches 2.73%. Those are numerical losses requiring finer checks. The analytic slender controls capture the expected topology changes, but change the physical core scale. Agreement of some plots therefore establishes neither quantitative GPE agreement nor convergence of post-event helicity. Retained GPE trefoil reconnections near t=0.387 are themselves wider-core local results, not the original paper’s full-resolution simulation.')
 for case in ['hopf','trefoil']:body.append(image(f'figures/{case}_ghost_comparison.png'))
 add('Kelvin-wave interpretation','The baseline animations show physical t and t*. The ring is shown in laboratory coordinates; knot/link movies use a clearly labeled comoving view. The analysis removes center translation and the best-fit plane tilt, then decomposes radial and axial centerline displacement into azimuthal modes where the projection winds monotonically. Only modes with at least eight original filament nodes per wavelength are retained. Low modes are large-scale deformation; their amplitudes and relative phases are recorded separately. Nonplanarity and resolved helical components support a disturbed centerline. They do not establish a dispersion relation, broadband cascade, phonon radiation, or the paper’s GPE density spectrum. Mode information beyond the resolved filament scale is not physically interpretable. The strongest next experiment is a compatible prepared GPE single ring with the same c, xi, Gamma and domain, followed by a thinner-core GPE knot/link comparison and finer VFM reconnection-distance study; this work did not launch that GPE experiment.')
 body.append(image('figures/shape_modes.png'));body.append(image('figures/scale_separation.png'))
 add('Scientific references','Clark di Leoni, Mininni & Brachet (PRA 94, 043605, 2016) uses GPE and reports topology-dependent helicity behavior and Kelvin/sound signatures. Its published knot simulations use 256³, not the retained local 64³ adaptations. Hänninen, Hietala & Salman (Scientific Reports 6, 37571, 2016) distinguishes centerline helicity from twist-inclusive framing; its Figure 4 trefoil is at zero temperature, while Figure 5 Hopf reconnection uses enlarged cores and alpha=1. That friction is not adopted here. Ricca, Samuels & Barenghi (JFM 391, 1999) compares full Biot–Savart and LIA knot dynamics and stresses thin-filament scale separation. Maggioni et al. (PRE 82, 026309, 2010) examines velocity, energy and writhe/twist of different torus geometries; its slender-core dimensional parameters are not copied as GPE parameters.')
 body.append('<p><a href="https://doi.org/10.1103/PhysRevA.94.043605">Target PRA paper</a> · <a href="https://doi.org/10.1038/srep37571">Hänninen et al.</a> · <a href="https://doi.org/10.1017/S0022112099005224">Ricca et al.</a> · <a href="https://doi.org/10.1103/PhysRevE.82.026309">Maggioni et al.</a></p>')
 add('Reproduction and provenance','The pinned Project.toml and Manifest.toml were copied into this new directory; no package upgrade was performed. Run ./run.sh inputs/NEW_CASE.toml after copying a saved configuration and changing its name. Existing run directories are refused. Use python3 batch_analysis.py, compare.py, extra_analysis.py, validation.py and report.py for derived products. prepare.py reuses retained GHOST fields and caches; reference tracing/knot code is copied under reference_tools. Julia benchmark_final.jl checks ring conventions and checkpoint continuation. audit_operations.jl performs the short operation-budget runs. Each run has configuration, diagnostics, event list, sparse curves, restart checkpoints, and completion status. The analysis/provenance.json source-group mapping is authoritative for the two early batches, whose original driver copied the on-disk source while code was being improved; exact loaded source versions were preserved separately. Later runs capture source at process startup. restart.jl is an optional geometry/clock restart helper and resets cumulative counters; use the load_checkpoint API demonstrated and executed in benchmark_final.jl when exact solver-state/counter continuity is required. The geometry-only restart helper has not been executed as a separate production run; only the exact-state checkpoint continuation test is claimed as validated. A run’s actual final time can exceed its requested endpoint by one accepted step, and that actual time appears everywhere.')
 body.append('<p><a href="REPRODUCE.txt">Detailed launch and restart instructions</a> · <a href="analysis/validation_checks.json">Executed validation checks</a> · <a href="analysis/costs.json">Runtime, memory and output costs</a> · <a href="analysis/operation_budgets.json">Reconnection/refinement energy accounting</a> · <a href="analysis/writhe_crosscheck.json">Independent writhe diagnostic check</a> · <a href="analysis/final_provenance.json">Final artifact provenance</a> · <a href="SHA256SUMS">Artifact checksums</a></p>')
 body.append('<h2>Executed run inventory</h2>');body.append(table(['Run','Core a','Initial input','Final t','Status','Seconds','Final nodes','Recon.'],[[name,c['a'],c['input'],z['final_time'],z['status'],z['elapsed_seconds'],z['nodes'],z['reconnections']] for name,c,z in sorted(completed)]))
 body.append('<h2>Figures and movies</h2>')
 for case in ['ring','hopf','trefoil']:
  name=case+'_base';body.append('<h3>'+case+'</h3>'+image(f'figures/{name}/snapshots.png')+f'<p><a href="figures/{name}/evolution.mp4">MP4 animation</a> · <a href="figures/{name}/evolution.gif">GIF</a> · <a href="figures/{name}/diagnostics.pdf">Diagnostics PDF</a> · <a href="runs/{name}/config.toml">Exact configuration</a></p>')
 style='body{font:16px/1.5 system-ui,sans-serif;max-width:1150px;margin:35px auto;padding:0 24px;color:#172333}h1,h2{color:#17435a}table{border-collapse:collapse;font-size:12px;width:100%;margin:20px 0}td,th{border:1px solid #bbc8d2;padding:6px;text-align:left}tr:nth-child(even){background:#f1f5f8}img{max-width:100%;margin:15px 0}a{color:#075c91}p{white-space:normal}'
 (ROOT/'REPORT.html').write_text('<!doctype html><html><meta charset="utf-8"><title>Local vortex simulations</title><style>'+style+'</style><body>'+''.join(body)+'</body></html>')
 (ROOT/'REPORT.txt').write_text('\n\n'.join(title+'\n'+content for title,content in text)+'\n')
 # Portable review PDF: concise findings and representative plots, with full tables in HTML/JSON.
 with PdfPages(ROOT/'REPORT.pdf') as pdf:
  fig=plt.figure(figsize=(8.3,11.7));y=.95
